import React, { useState, useEffect, useRef } from 'react';
import { LOGIN_URL, PROFILE_URL } from '../config';
import styled from 'styled-components';
import Alert from 'react-bootstrap/Alert';
import { MenuItem, Select, FormControl, Chip } from '@mui/material';
import { useLocation } from './AreaContext';

const LoginPage = styled.div`
  display: flex;
  height: 100vh;
  overflow: auto;
  background-color: #111;
  @media (max-width: 800px) {
    flex-direction: column;
  }
`;

const ContentSection = styled.div`
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 30px;
  background: linear-gradient(to right, #011328, #0e2c4f);
  color: white;
  z-index: 1;
  min-height: 100vh;
  overflow: hidden;

  @media (max-width: 800px) {
    width: 100%;
    flex: none;
    order: 1;
  }
`;

const ImageSection = styled.div`
  position: relative;
  flex: 1;
  background: #262626;
  background: linear-gradient(0deg,rgba(25, 25, 25, 1) 0%, rgba(0, 0, 0, 1) 100%);
  height: 100%;
  user-select: none;
  overflow: hidden;

  @media (max-width: 800px) {
    display: block;
    width: 100%;
    flex: none;
    order: 2;
  }
`;

const Title = styled.h1`
  font-size: 2.2rem;
  margin-top: 20px;
  margin-bottom: 20px;
  text-align: center;
  color: #dfebeb;
  font-weight: 700;

  letter-spacing: 1px;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.4);
`;

const LoginButton = styled.button`
  background-color: #176498;
  color: white;
  padding: 6px;
  border: none;
  font-size: 12pt;
  cursor: pointer;
  width: 100%;
  height: 40px;

  &:hover {
    background-color: #0056b3;
  }

  @media (max-width: 768px) {
    width: 100%;
    font-size: 1rem;
  }
`;

const DottedMap = styled.img`
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  max-width: 800px;
  opacity: 0.3;
  pointer-events: none;
  z-index: -1;
  left: 50%;
  transform: translateX(-50%);
`;

const Logo = styled.img`
  margin-top: 20px;
  margin-right: 20px;
  width: auto;
  height: 60px;
  display: inline;
`;

const LoadingContainer = styled.div`
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  height: 100vh;
  background-color: black;
  color: white;
`;

const LoadingText = styled.p`
  font-size: 1.0rem;
  margin-bottom: 20px;
`;

const LoadingGif = styled.img`
  width: 16px;
  height: 16px;
  margin-left: 10px;
`;

const ColorExplanation = styled.div`
  position: absolute;
  bottom: 30px;
  left: 50%;
  transform: translateX(-50%);
  color: white;
  font-size: 0.9rem;
  display: flex;
  justify-content: center;
  gap: 16px;
  z-index: 100;
  flex-wrap: no-wrap;
  text-align: center;
  width: 100%;
`;

// ----- AREA CONFIG LIST -----
const areas = [
  { value: 'efin', label: 'EFINZAMC | Finland', home: true },
  { value: 'edxx', label: 'EDXXZAMC | Germany', chip: { label: 'Pre-operational', className: 'preoperational' } },
  { value: 'egxx', label: 'EGXXZAMC | United Kingdom', chip: { label: 'Pre-operational', className: 'preoperational' } },
  { value: 'eett', label: 'EETTZAMC | Estonia' },
  { value: 'eacc', label: 'EACCZAMC | Amswell', chip: { label: 'Test environment', className: 'testenvironment' } },
];

const Login = ({clusterIsActiveMap}) => {
  const [loginError, setLoginError] = useState(null);
  const [loading, setLoading] = useState(true);
  const { selectedLocation, setSelectedLocation } = useLocation();
  const [currentImage, setCurrentImage] = useState(0);
  const intervalRef = useRef(null);
  const images = ['images/login1.svg', 'images/login3.png', 'images/login2.png', 'images/login4.jpg'];

  const startInterval = () => {
    intervalRef.current = setInterval(() => {
      setCurrentImage(prev => (prev + 1) % images.length);
    }, 9000);
  };

  useEffect(() => {
    startInterval();
    return () => clearInterval(intervalRef.current);
  }, []);
  
  useEffect(() => {
    const checkAuthentication = async () => {
      try {
        const response = await fetch(PROFILE_URL, {
          credentials: 'include',
        });

        if (response.ok) {
          setLoginError('')
          window.location.href = '/';
        } else {
          setLoading(false);
          setLoginError('')
        }
      } catch (error) {
        console.error('Error checking authentication:', error);
        setLoading(false);
        setLoginError('Login Failed. If problems persist, please contact your system administrator.')
      }
    };

    checkAuthentication();
  }, []);

  const handleLogin = () => {
    if (selectedLocation) {
      window.location.href = LOGIN_URL;
    } else {
      setLoginError('Please select area first.');
    }
  };  

  const handleDotClick = (idx) => {
    setCurrentImage(idx);
    clearInterval(intervalRef.current);
    intervalRef.current = null;
  };

  if (loading) {
    return (
      <LoadingContainer>
        <LoadingText>
          Loading
          <LoadingGif src="images/ajax-loader.gif" alt="Loading" />
        </LoadingText>
      </LoadingContainer>
    );
  }

  return (
    <LoginPage>
      <ImageSection bgImage={'images/map.png'}>
        {images.map((img, index) => (
          <img
            key={index}
            src={img}
            alt={`Slide ${index + 1}`}
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              opacity: currentImage === index ? 0.7 : 0,
              transition: 'opacity 1s ease-in-out',
              zIndex: currentImage === index ? 1 : 0,
              pointerEvents: 'none',
            }}
          />
        ))}

        {currentImage === 0 && (
          <ColorExplanation>
            <p style={{ background: '#e51792', padding: '2px 4px', fontSize: '10pt', opacity: 0.7 }}>Considering</p> 
            <p style={{ background: '#ff7f00', padding: '2px 4px', fontSize: '10pt', opacity: 0.7 }}>Under Development</p> 
            <p style={{ background: '#3e9e00', padding: '2px 4px', fontSize: '10pt', opacity: 0.7 }}>Implemented</p> 
          </ColorExplanation>
        )}

        {currentImage === 3 && (
          <ColorExplanation>
            <p className='slogan-text-2' style={{fontSize: '1rem'}}>
              Subdivision staff? Contact us to add your FIR.
            </p>
          </ColorExplanation>
        )}

        <div style={{ position: 'absolute', bottom: 10, left: '50%', transform: 'translateX(-50%)', display: 'flex', gap: 8 }}>
          {images.map((_, idx) => (
            <div
              key={idx}
              onClick={() => handleDotClick(idx)}
              style={{
                width: 11,
                height: 11,
                borderRadius: '50%',
                background: idx === currentImage ? '#fff' : '#484b4c',
                cursor: 'pointer',
                transition: 'background 0.3s',
                pointerEvents: 'all',
                zIndex: 999
              }}
            />
          ))}
        </div>
      </ImageSection>

      <ContentSection>
        <DottedMap className='login-map-2' src='images/map2.png'></DottedMap>

        <div style={{ display: 'inline', alignItems: 'center'}}>
          <Logo src="images/logo.svg" alt="VATSIM Scandinavia" />
          <Logo src='images/vlara-logo.svg' alt='V-LARA' style={{height: '36px', marginLeft: '10px'}}/>
        </div>

        <Title>LARA Web Booking Client</Title>

        <div style={{ display: 'flex', alignItems: 'center', width: '100%', marginBottom: '20px' }}>
          <FormControl style={{ marginRight: '10px', flex: 1 }}>

            <Select className="text-fields no-border-radius" id="area-select" value={selectedLocation} onChange={(e) => setSelectedLocation(e.target.value)} size="small">
            {areas
              .slice()
              .sort((a, b) => {
                // Keep 'efin' always on top
                if (a.value === 'efin') return -1; if (b.value === 'efin') return 1;

                // Determine sort weight for each item
                const getWeight = (item) => {
                  if (item.chip) {
                    switch (item.chip.className) {
                      case 'preoperational':
                        return 2;
                      case 'notoperational':
                        return 3;
                      case 'testenvironment':
                        return 4;
                      default:
                        return 5; // unknown, put last
                    }
                  } else if (clusterIsActiveMap[item.value]) {
                    return 1; // operational on top
                  } else {
                    return 3; // not operational
                  }
                };

                return getWeight(a) - getWeight(b);
              })
              .map(({ value, label, chip, home }) => (
                <MenuItem key={value} value={value} style={{ display: 'flex', alignItems: 'center' }}>
                  <span
                    style={{
                      flex: 1,
                      fontWeight: clusterIsActiveMap[value] ? 'bold' : 'normal',
                      color: clusterIsActiveMap[value] ? '#41826e' : 'inherit'
                    }}
                    className={home ? "login-finland" : ""}
                  >
                    {label}
                  </span>

                  {chip ? (
                    <Chip
                      label={chip.label}
                      size="small"
                      className={`status-chip ${chip.className}`}
                      style={{ marginLeft: 8 }}
                    />
                  ) : clusterIsActiveMap[value] ? (
                    <Chip
                      label="Operational"
                      size="small"
                      className="status-chip operational"
                      style={{ marginLeft: 8 }}
                    />
                  ) : (
                    <Chip
                      label="Not operational"
                      size="small"
                      className="status-chip notoperational"
                      style={{ marginLeft: 8 }}
                    />
                  )}
                </MenuItem>
              ))}
            </Select>

          </FormControl>
          <LoginButton onClick={handleLogin} style={{ flex: 1 }}>Login with VATSIM</LoginButton>
        </div>


        {loginError && <p style={{ color: 'red' }}>{loginError}</p>}

        <Alert key={'success'} variant={'success'} style={{width: '100%', borderRadius: '0'}}>
          <b>Local and sub-regional airspace management support system</b><br/>
          Create and manage airspace reservations on VATSIM network!
        </Alert>


        <p className='slogan-text-2'>Supporting VATSIM Aviation</p>

        <div className='flag-container'>
          <a href="https://vatsim-scandinavia.org/" target="_blank" rel="noopener noreferrer">
            <img src="https://flagcdn.com/h40/fi.png" alt="Finland" title="Finland" />
          </a>
          <a href="https://vatsim-germany.org/" target="_blank" rel="noopener noreferrer">
            <img src="https://flagcdn.com/h40/de.png" alt="Germany" title="Germany" />
          </a>
          <a href="https://www.vatsim.uk/" target="_blank" rel="noopener noreferrer">
            <img src="https://flagcdn.com/h40/gb.png" alt="United Kingdom" title="United Kingdom" />
          </a>
          <a href="https://virtualnato.org/home/" target="_blank" rel="noopener noreferrer">
            <img src="images/vNato.png" alt="vNATO" title="vNATO" />
          </a>
        </div>

      </ContentSection>
    </LoginPage>
  );
};

export default Login;


